  return `<div class="game-world cooperative game-finished cooperative-victory"><header class="game-hud"><div class="hud-brand"><img class="game-brand-logo" src="assets/cyberrota-logo.svg" alt="Cyber Rota"><span class="game-brand-mode"><small>DEFENDA A REDE · MISSÃO CONCLUÍDA</small></span></div><div class="hud-center"><span class="round-badge">RODADA ${game.coop.round}</span><span class="round-badge">CASA ${game.coop.position}/18</span><span class="hacker-hud"><i></i> HACKER <b>0 PV</b></span></div><button class="hud-sound" data-action="toggle-sound" aria-label="${soundMuted?'Ativar':'Silenciar'} música e efeitos" aria-pressed="${!soundMuted}">${uiIcon(soundMuted?'volume-off':'volume')}</button></header><div class="victory-layout"><section class="victory-stage sequence-${stage}" aria-label="Tabuleiro após a vitória" data-victory-stage="${stage}">${renderCoopBoardScene()}${announcement}</section><aside class="victory-summary"><div class="victory-stats"><b>${game.coop.log.length} rodadas</b><span>${alive}/5 servidores ainda ativos</span><span>Peças da armadura espalhadas no relé</span></div>${game.sessionErrors.length?`<section class="victory-errors"><h2>Cartas para revisar</h2>${renderErrorRows(game.sessionErrors)}</section>`:'<p class="victory-clean">Nenhuma carta errada nesta partida. Excelente!</p>'}${stage==='button'?renderMultiplayerPodium():''}</aside></div></div>`;
