function renderArmorDebris(armorStage, armorMotion){
  const parts=[
    {group:1,name:'back-left',x:-86,y:184,angle:-52,path:'<path d="M-41-38 -81-48 -71-8 -48 5Z"/>'},
    {group:1,name:'back-right',x:86,y:184,angle:52,path:'<path d="M41-38 81-48 71-8 48 5Z"/>'},
    {group:2,name:'antenna-left',x:-42,y:222,angle:-68,path:'<path d="M-34-70 -45-99"/><circle cx="-45" cy="-102" r="7"/>'},
    {group:2,name:'antenna-right',x:42,y:222,angle:68,path:'<path d="M34-70 45-99"/><circle cx="45" cy="-102" r="7"/>'},
    {group:3,name:'shoulder-left',x:-125,y:184,angle:-46,path:'<path d="M-59-43 -82-56Q-88-60-94-55L-106-39Q-111-32-106-25L-88-11Q-80-7-73-13L-57-27Z"/>'},
    {group:3,name:'shoulder-right',x:125,y:184,angle:46,path:'<path d="M59-43 82-56Q88-60 94-55L106-39Q111-32 106-25L88-11Q80-7 73-13L57-27Z"/>'},
    {group:4,name:'forearm-left',x:-171,y:229,angle:-72,path:'<path d="M-69 47 -82 65 -72 84 -53 76 -49 58Z"/>'},
    {group:4,name:'forearm-right',x:171,y:229,angle:72,path:'<path d="M69 47 82 65 72 84 53 76 49 58Z"/>'},
    {group:5,name:'chest',x:0,y:206,angle:0,path:'<path d="M-35 31 -23 24 -10 39H10L23 24 35 31 30 68 18 83H-18L-30 68Z"/>'},
  ];
  const currentStage=Math.max(0,Math.min(5,Number(armorStage)||0));
  const motion=armorMotion||null;
  const fragments=parts.map((part)=>{
    const detached=part.group<=currentStage;
    const dropping=motion?.type==='drop'&&part.group===motion.to;
    const returning=motion?.type==='repair'&&part.group===motion.from;
    if(!detached&&!returning)return '';
    const transform=`translate(${part.x} ${part.y}) rotate(${part.angle})`;
    const state=dropping?'drop-now':returning?'return-now':'landed';
    const style=`--fall-x:${part.x}px;--fall-y:${part.y}px;--fall-angle:${part.angle}deg`;
    return `<g class="armor-debris-part ${part.name} ${state}" style="${style}" transform="${transform}"><g class="armor-fragment">${part.path}</g></g>`;
  }).join('');
  return fragments?`<g class="boss-debris" transform="translate(500 -67) scale(.47)">${fragments}</g>`:'';
}
